export function buildCurrentAuthorizedProductQuestionWorkspaceV1(input:{organizationId:string;questionId:string;subjectId:string;purpose:string;scopeDigest:string;sensitivity:"standard"|"restricted"|"private";evaluatedAt:string;candidates:readonly CurrentArtifactDeliveryCandidateV1[]}):CurrentAuthorizedProductQuestionWorkspaceV1{const artifacts=input.candidates.filter(item=>item.access.disposition==="eligible"&&item.safeProjection).map(item=>item.safeProjection!);const history=deriveCurrentAuthorizedLeadershipHistoryV1(input.candidates);const accessResultDigests=input.candidates.filter(item=>item.access.disposition==="eligible").map(item=>item.access.resultDigest).sort();const unsigned={contractVersion:"1" as const,organizationId:input.organizationId,questionId:input.questionId,subjectId:input.subjectId,purpose:input.purpose,scopeDigest:input.scopeDigest,sensitivity:input.sensitivity,evaluatedAt:input.evaluatedAt,artifacts,history,accessResultDigests};return{...unsigned,workspaceDigest:productArtifactBodyDigest(unsigned)}}
